function showFrame(index){if(!current?.steps.length)return;frameIndex=Math.max(0,Math.min(current.steps.length-1,index));const step=current.steps[frameIndex],focus=step.focus||{};const src=safeAsset(step.screenshot);$('frame').hidden=!src;$('image-missing').hidden=!!src;if(src)$('frame').src=src;$('frame').alt=`Evidence frame ${frameIndex+1}: ${step.key}; focus on ${focus.name||focus.tag||'document'}`;$('frame-label').textContent=`${frameIndex+1} / ${current.steps.length}`;$('scrubber').value=frameIndex;$('capture-key').textContent=`${step.key} · ${(step.elapsedMs/1000).toFixed(2)}s`;$('focus-name').textContent=focus.tag==='body'?'Document body':(focus.name||'No named element');$('keycap').textContent=step.key;$('phase').textContent=step.phase;$('step-badge').textContent=String(frameIndex).padStart(2,'0');$('step-note').textContent=step.note||'Captured after the input event.';$('frame-hash').textContent=step.sha256||'Not supplied';$('focus-details').replaceChildren(...Object.entries({'Element':focus.tag||'—','DOM id':focus.id||'—','Explicit role':focus.role||'native / none','tabIndex':String(focus.tabIndex??'—'),':focus-visible':String(focus.focusVisible??'—'),'Outline':focus.outline||'—'}).map(([k,v])=>element('div',{},[element('dt',{text:k}),element('dd',{text:v})])));for(const row of $('trace').children)row.classList.toggle('selected',Number(row.dataset.index)===frameIndex);}
