function save(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=element('a',{href:url,download:name});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Reproduction copied.');}catch{save(text,'keyboard-bug-report.md','text/markdown');}}
function info(title,paragraphs,code){const host=$('info-content');host.replaceChildren(element('span',{class:'eyebrow',text:'CAN I FINISH? / EVIDENCE LAB'}),element('h2',{text:title}),...paragraphs.map(text=>element('p',{text})));if(code)host.append(element('pre',{text:code}));$('info-dialog').showModal();}
const limitations=['A completed task is not an accessibility certification. This prototype observes one explicit keyboard contract in one Chromium browser and viewport.','A task target not reached by a bounded Tab sequence may require another documented key or a different contract. Normal modal focus containment is not itself a defect.','Focus visibility is recorded as DOM/CSS metadata and screenshots, not automatically judged for visual contrast. Shadow DOM, cross-origin frames, screen readers, authentication, mobile and broad WCAG auditing are outside this prototype’s tested scope.','The sample site and fixes are controlled fixtures. Real-user validation and independent production-site evaluation are future work. Screenshots can contain page content: keep reports private unless you intend to share them.','The hosted workspace displays recorded real runs. New runs execute only when you launch the local Node.js runner. No paid browser service or model API is used.'];
$('frame').onerror=()=>{$('frame').hidden=true;$('image-missing').hidden=false;};$('play').onclick=()=>{if(timer){stop();return;}if(frameIndex>=current.steps.length-1)showFrame(0);$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause recorded focus sequence');timer=setInterval(()=>{if(frameIndex>=current.steps.length-1)stop();else showFrame(frameIndex+1);},900);};$('previous').onclick=()=>{stop();showFrame(frameIndex-1);};$('next').onclick=()=>{stop();showFrame(frameIndex+1);};$('scrubber').oninput=e=>{stop();showFrame(Number(e.target.value));};
for(const b of document.querySelectorAll('[data-journey]'))b.onclick=()=>{journey=b.dataset.journey;variant='broken';selectRun();};$('broken').onclick=()=>{variant='broken';selectRun();};$('fixed').onclick=()=>{variant='fixed';selectRun();};for(const b of document.querySelectorAll('[data-view]')){b.onclick=()=>setView(b.dataset.view);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-view]')];let i=tabs.indexOf(b);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setView(tabs[i].dataset.view);tabs[i].focus();};}$('compare-button').onclick=()=>{if(current?.external){journey='registration';variant='broken';selectRun();}setView('compare');};
$('export-json').onclick=()=>{if(current)save(JSON.stringify(current,null,2),`${current.id}.json`);};$('export-contract').onclick=()=>{if(current)save(JSON.stringify(current.contract,null,2),'keyboard-contract.json');};$('export-test').onclick=()=>{if(current)save(regressionTest(current),'keyboard-regression.mjs','text/javascript');};$('copy-repro').onclick=()=>copy(bugReport(current));$('contract').onclick=()=>{if(current)info('The task contract',['An explicit sequence of keyboard actions and expected visible states. The runner cannot silently switch to mouse input to make it pass.'],JSON.stringify(current.contract,null,2));};$('limitations').onclick=()=>info('What the evidence can tell you.',limitations);$('method').onclick=()=>info('Keys in. Evidence out.',['The local runner opens a fresh Chromium context, navigates to the URL, and sends native Playwright keyboard events. It never uses a mouse click or locator.focus() to reach the contract’s targets.','After each key, it records the focused element, timing, screenshot, and SHA-256 hash. A browser video captures the actual sequence. Target matching uses accessible roles and names.','A failed assertion stops the contract. For a dialog that remains open after Escape, a small diagnostic probe records additional Tab/Shift+Tab behavior. The report labels this evidence without declaring automatic WCAG nonconformance.','Compare repeats the same contract against the fixed fixture. All metrics come from the saved reports. Screenshot-backed playback is separate from the native browser recording.']);
for(const b of document.querySelectorAll('.close-dialog'))b.onclick=()=>b.closest('dialog').close();function openRun(){$('run-dialog').showModal();$('run-status').textContent='';if(current)$('contract-json').value=JSON.stringify(current.contract,null,2);$('run-journey').value=['registration','dialog'].includes(journey)?journey:'registration';$('run-version').value=variant;}$('new-run').onclick=openRun;$('rerun').onclick=openRun;$('run-kind').onchange=()=>{const custom=$('run-kind').value==='custom';$('custom-options').hidden=!custom;$('fixture-options').hidden=custom;};
$('run-form').onsubmit=async event=>{event.preventDefault();if(!local)return;$('run-submit').disabled=true;$('run-status').textContent='Running Chromium. Capturing keys, focus, screenshots, and video…';try{const custom=$('run-kind').value==='custom';const body=custom?{url:$('target-url').value,contract:JSON.parse($('contract-json').value)}:{fixture:$('run-journey').value,version:$('run-version').value};const response=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Run failed');const report=validateReport(data.report);if(!custom){report.fixture={journey:body.fixture,version:body.version,publicPath:`fixtures/campus.html?journey=${body.fixture}&version=${body.version}`};runs=runs.filter(r=>!(r.fixture?.journey===body.fixture&&r.fixture?.version===body.version));journey=body.fixture;variant=body.version;}else{journey=report.id;}runs.push(report);selectRun();setView('replay');$('run-dialog').close();toast(`New browser run: ${report.outcome}.`);}catch(error){$('run-status').textContent=error.message;}finally{$('run-submit').disabled=false;}};
$('import').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>8e6){toast('Choose a report under 8 MB.');return;}try{const r=validateReport(JSON.parse(await file.text()));runs=runs.filter(existing=>existing.id!==r.id);runs.push(r);journey=r.id;selectRun();setView('replay');toast('Report imported. Serve its evidence assets locally to display screenshots.');}catch(error){toast(error.message);}event.target.value='';};
try{const response=await fetch('evidence/demo.json');if(!response.ok)throw new Error('Evidence bundle could not be loaded. Run npm run demo to generate it.');const data=await response.json();runs=data.runs.map(validateReport);try{const c=await fetch('evidence/checkout.json');if(c.ok)runs.push(...(await c.json()).runs.map(validateReport));}catch{}try{const external=await fetch('evidence/apple-voiceover.json');if(external.ok){const apple=validateReport(await external.json());runs.push(apple);if(new URLSearchParams(location.search).get('journey')!=='checkout')journey=apple.id;}}catch{}$('generated').textContent='Captured '+new Date(data.generatedAt).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})+'.';selectRun();}catch(error){$('loading').className='error-message';$('loading').textContent=error.message;}
try{if(['127.0.0.1','localhost'].includes(location.hostname)){const r=await fetch('/api/status');const status=await r.json();local=status.localRunner===true;}}catch{/* Hosted static viewer. */}
$('runner-label').textContent=local?'Local runner connected':'Recorded evidence viewer';$('runner-dot').classList.toggle('ready',local);$('local-setup').hidden=local;$('run-form').hidden=!local;$('local-explanation').textContent=local?'Connected to your local runner. Each run opens an isolated browser context with no saved login.':'This hosted page displays real captured runs. Start the free local runner to test a new URL or rerun the fixtures.';$('source-link').href='https://github.com/JayadityaVetsa/can-i-finish/archive/refs/heads/main.zip';

function decorateRun(){
 const external=!!current.external;
 $('finish-goal').textContent=current.contract.goal||'Defined task assertion';
 $('workspace-site').replaceChildren(document.createTextNode(external?'Apple.com':'Northstar Campus'),element('small',{text:external?'Independent live-site observation':'Controlled demonstration'}));
 $('breadcrumb-site').textContent=external?'Apple.com':'Northstar Campus';
 if(external)$('crumb').textContent='iPhone VoiceOver setup';
 document.querySelector('.variant-control').hidden=external||!current.fixture;
 $('compare-button').textContent=external?'See a controlled fix comparison ↗':'Compare before & after ↗';
 $('frame').style.aspectRatio=`${current.engine?.viewport?.width||1280} / ${current.engine?.viewport?.height||900}`;
 if(external){$('fixture-link').hidden=false;$('fixture-link').textContent='Open Apple task page ↗';$('fixture-link').href='https://www.apple.com/accessibility/';$('run-summary').textContent=current.outcome==='passed'?'Reached Apple’s iPhone VoiceOver setup article using only the recorded keyboard sequence. This is one task observation, not an audit of Apple.':current.findings[0]?.summary||'The recorded sequence did not complete.';}
 else $('fixture-link').textContent='Try fixture ↗';
}
